  @text innerVoice
@endcard

@card "TINY THEATRE / 小剧场"
  @text theatreOpening
  @text theatreDialogue
  @text theatreEnding
@endcard

@card "RECENTLY SEEN & READ"
  @quote workQuote
  @text workMeta
@endcard

@card "NOW PLAYING"
  @text songTitle
  @text songArtist
  @text listeningNote
@endcard

@footer PRIVATE EDITION · VERDANT HOURS

